CREATE OR ALTER PROCEDURE [dbo].[SP_ChangePassword] @UserId INT, @NewPassword VARCHAR(100) AS BEGIN SET NOCOUNT OFF; BEGIN TRY UPDATE [USER_MASTER] SET [UM_PASSWORD] = @NewPassword WHERE [UM_CODE] = @UserId AND [ES_DELETE] = 0 END TRY BEGIN CATCH DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE() DECLARE @ErrorSeverity INT = ERROR_SEVERITY() DECLARE @ErrorState INT = ERROR_STATE() RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState) END CATCH END